      implicit none
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: status
      if (status /= HIPSPARSE_STATUS_SUCCESS) then
        write (*, *) "HIPSPARSE ERROR: code = ", status
        stop 1
      end if
    end subroutine hipsparseCheck

